297	    @Override
298	    @Transactional
299	    public void saveOwner(Owner owner) throws DataAccessException {
300	        saveOwner(owner, false);
301	    }
302	
303	    /**
304	     * Save an owner, enforcing the create-time business rules.
305	     *
306	     * <p>Duplicate rejection on create is expressed solely through the single {@code identityKey} (the
307	     * SHA-256 hex over the normalized telephone, lower-cased email and last-name Soundex, see
308	     * {@link Owner#identityKey(String, String, String)}): {@link #assertIdentityIsUnique(Owner)}
309	     * rejects an owner whose whole identity key already belongs to another owner. Because the
310	     * telephone is part of the key, two members of the same household (same last name and postcode)
311	     * with different telephones have different identity keys and are both allowed; the former separate
312	     * household-duplicate 409 no longer applies. Such an undeclared household member is created but
313	     * flagged as a possible (suspected) duplicate when its last-name Soundex and postcode match an
314	     * existing owner (see {@link #assignPossibleDuplicate(Owner, boolean)}), whereas a declared
315	     * household member ({@code sharesHousehold} set) is left unflagged; {@code sharesHousehold} now
316	     * governs only that flagging. This keeps the sole {@code POST /api/owners} duplicate rule in one
317	     * place and lets household members coexist, which the household membership-level ceiling (see
318	     * {@link #computeMembershipLevel(Owner)}) relies on to compare a new owner against the existing
319	     * members.
320	     */
321	    @Override
322	    @Transactional
323	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
324	        boolean isCreate = owner.isNew();
325	        assertEmailDomainAllowed(owner);
326	        assertIdentityIsUnique(owner);
327	        if (owner.isNew()) {
328	            assertCityHasCapacity(owner);
329	        }
330	        if (owner.getRegistrationDate() == null) {
331	            owner.setRegistrationDate(LocalDate.now());
332	        }
333	        assertRegistrationDateNotInFuture(owner);
334	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
335	        if (owner.isNew()) {
336	            assertDailyRegistrationLimit(owner);
337	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
338	            owner.setCapacityWarning(computeCapacityWarning(owner));
339	        }
340	        if (owner.isNew() && owner.getMemberId() == null) {
341	            owner.setMemberId(generateMemberId(owner));
342	        }
343	        if (owner.isNew() && owner.getNamesakeCount() == null) {
344	            owner.setNamesakeCount(countNamesakes(owner));
345	        }
346	        if (owner.isNew() && owner.getHouseholdCount() == null) {
347	            owner.setHouseholdCount(countHouseholdMembers(owner));
348	        }
349	        if (owner.isNew() && owner.getMembershipLevel() == null) {
350	            owner.setMembershipLevel(computeMembershipLevel(owner));
351	        }
352	        if (owner.isNew()) {
353	            assignPossibleDuplicate(owner, sharesHousehold);
354	        }
355	        ownerRepository.save(owner);
356	        if (isCreate) {
357	            int membershipLevel = owner.effectiveMembershipLevel();
358	            AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
359	                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
360	            OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQ.incrementAndGet(),
361	                owner.getId(), owner.primaryIdentifier(), membershipLevel, owner.ownerSegment());
362	            AUDIT.info(objectMapper.writeValueAsString(event));
363	            NOTIFY.info("welcome notification enqueued id={} memberId={}",
364	                owner.getId(), owner.getMemberId());
365	        }
366	    }
367	
368	    /**
369	     * Count the existing owners that, at the moment this owner is created, share its first name
370	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
371	     * it never counts itself. This value is deterministic given the current data, so it is computed
372	     * once at creation time and stored.
373	     */
374	    private Integer countNamesakes(Owner owner) {
375	        String firstName = owner.getFirstName();
376	        String lastName = owner.getLastName();
377	        if (firstName == null || lastName == null) {
378	            return 0;
379	        }
380	        return (int) ownerRepository.findAll().stream()
381	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
382	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
383	                && lastName.equalsIgnoreCase(existing.getLastName()))
384	            .count();
385	    }
386	
387	    /**
388	     * Count the members of this owner's household at the moment it is created, i.e. the number of
389	     * owners sharing its household id (same last name and postcode, see
390	     * {@link Owner#householdId(String, String)}) plus this owner itself. An owner with no derivable
391	     * household id (missing last name or postcode) is counted as a single-member household. The value
392	     * is deterministic given the current data, so it is computed once at creation time and stored.
393	     */
394	    private Integer countHouseholdMembers(Owner owner) {
395	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
396	        if (householdId == null) {
397	            return 1;
398	        }
399	        long others = ownerRepository.findAll().stream()
400	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
401	            .filter(existing -> householdId.equals(
402	                Owner.householdId(existing.getLastName(), existing.getPostcode())))
403	            .count();
404	        return (int) others + 1;
405	    }
406	
407	    /**
408	     * Compute a newly created owner's {@code membershipLevel} after applying the household level
409	     * ceiling, the value stored on the owner so every later read returns the capped level. The
410	     * owner's own uncapped level is first derived from its membership points (see
411	     * {@link Owner#membershipLevel(int)} and
412	     * {@link Owner#membershipPoints(Integer, String, Integer, java.time.LocalDate)}). The ceiling is
413	     * then one above the current maximum {@code membershipLevel} among the owner's existing household
414	     * members&mdash;other owners sharing its household id (same last name and postcode, see
415	     * {@link Owner#householdId(String, String)}), excluding soft-deleted owners and the owner itself.
416	     * Each level (the owner's own uncapped level and each member's) is read through
417	     * {@link Owner#effectiveMembershipLevel()}, the single resolver shared with the read-side mapping.
418	     * The returned level is the smaller of the uncapped level and that ceiling. When the owner has no
419	     * derivable household id or no existing household member, no ceiling applies and the uncapped
420	     * level is returned.
421	     */
422	    private Integer computeMembershipLevel(Owner owner) {
423	        int uncapped = owner.effectiveMembershipLevel();
424	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
425	        if (householdId == null) {
426	            return uncapped;
427	        }
428	        Integer maxHouseholdLevel = ownerRepository.findAll().stream()
429	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
430	            .filter(existing -> !existing.isDeleted())
431	            .filter(existing -> householdId.equals(
432	                Owner.householdId(existing.getLastName(), existing.getPostcode())))
433	            .map(Owner::effectiveMembershipLevel)
434	            .max(Integer::compareTo)
435	            .orElse(null);
436	        if (maxHouseholdLevel == null) {
437	            return uncapped;
438	        }
439	        return Math.min(uncapped, maxHouseholdLevel + 1);
440	    }
441	
442	    /**
443	     * Build an owner's {@code memberId} formatted {@code '<REGION><FY><HASH8><CHK>'}, where
444	     * {@code REGION} is the region code derived from the owner's postcode (or {@code 'UNKNOWN'} when no
445	     * region can be derived), {@code FY} is the two-digit fiscal year of the registration date,
446	     * {@code HASH8} is the first eight upper-cased hex characters of SHA-256 over the owner's normalized
447	     * telephone concatenated with the last name, and {@code CHK} is a single Luhn check digit over the
448	     * digits of the {@code <REGION><FY><HASH8>} prefix (e.g. {@code 'NSW271A2B3C4D5'}). The base value
449	     * is deterministic in those fields and carries no sequence number (see
450	     * {@link Owner#memberId(String, String, String, java.time.LocalDate)}).
451	     *
452	     * <p>When that computed id collides with an existing owner's {@code memberId}, this appends
453	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g. a second owner
454	     * computing {@code 'NSW271A2B3C4D5'} is stored as {@code 'NSW271A2B3C4D5-2'}), so distinct owners
455	     * always receive distinct member ids. A {@code null} computed id (missing telephone, last name or
456	     * registration date) is returned unchanged.
457	     */
458	    private String generateMemberId(Owner owner) {
459	        String base = Owner.memberId(owner.getPostcode(), owner.getTelephone(), owner.getLastName(),
460	            owner.getRegistrationDate());
461	        if (base == null) {
462	            return null;
463	        }
464	        Set<String> existing = ownerRepository.findAll().stream()
465	            .filter(other -> !Objects.equals(other.getId(), owner.getId()))
466	            .map(Owner::getMemberId)
467	            .filter(Objects::nonNull)
468	            .collect(Collectors.toSet());
469	        if (!existing.contains(base)) {
470	            return base;
471	        }
472	        int n = 2;
473	        while (existing.contains(base + "-" + n)) {
474	            n++;
475	        }
476	        return base + "-" + n;
477	    }
478	
479	    /**
480	     * Flag a newly created owner as a possible (soft) duplicate of an existing owner. A hard
481	     * duplicate (an owner sharing this owner's whole {@code identityKey}) has already been rejected by
482	     * {@link #assertIdentityIsUnique(Owner)} before this runs. This detects the weaker overlap: an
483	     * existing owner whose identity key <em>differs</em> but whose last-name Soundex (see
484	     * {@link Owner#soundex(String)}) and postcode both match this owner. When such an owner exists,
485	     * {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to the matching
486	     * owner's id (the lowest id when several match); otherwise {@code possibleDuplicate} is set
487	     * {@code false} and {@code possibleDuplicateOf} left unset. In particular, two owners with the same
488	     * last name and postcode but different telephones are no longer a hard duplicate and surface here
489	     * as a soft match.
490	     *
491	     * <p>A declared household member ({@code sharesHousehold} set) is never a suspected duplicate: it
492	     * deliberately joins an existing household, so it is left unflagged.
493	     */
494	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
495	        if (sharesHousehold) {
496	            owner.setPossibleDuplicate(false);
497	            owner.setPossibleDuplicateOf(null);
498	            return;
499	        }
500	        String identityKey = Owner.identityKey(
501	            owner.getTelephone(), owner.getEmail(), owner.getLastName());
502	        String soundex = Owner.soundex(owner.getLastName());
503	        String postcode = owner.getPostcode();
504	        Integer match = null;
