305	    /**
306	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
307	     * source of truth for how an email is persisted, so inputs that differ only in letter case
308	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
309	     * (create and update, mapper or hand-copied) stores the same canonical value.
310	     *
311	     * @param email the raw email, possibly {@code null}
312	     * @return the lower-cased form, or {@code null} if the input was {@code null}
313	     */
314	    public static String normalizeEmail(String email) {
315	        return email == null ? null : email.toLowerCase();
316	    }
317	
318	    /**
319	     * Disposable email domains that are not accepted for an owner. Compared case-insensitively
320	     * against the domain part of the owner's email (see {@link #isDisposableEmailDomain(String)}).
321	     */
322	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
323	        "mailinator.com",
324	        "tempmail.com",
325	        "guerrillamail.com");
326	
327	    /**
328	     * Check whether an email's domain is on the disposable-domain blocklist. The domain is the text
329	     * after the last {@code '@'}, compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}.
330	     * This is the single source of truth for which email domains are rejected, shared by any
331	     * persistence path. A {@code null} or empty email, or one with no {@code '@'}, is not disposable.
332	     *
333	     * @param email the owner's email, possibly {@code null}
334	     * @return {@code true} if the email's domain is on the blocklist, {@code false} otherwise
335	     */
336	    public static boolean isDisposableEmailDomain(String email) {
337	        if (email == null) {
338	            return false;
339	        }
340	        int at = email.lastIndexOf('@');
341	        if (at < 0) {
342	            return false;
343	        }
344	        String domain = email.substring(at + 1).toLowerCase();
345	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
346	    }
347	
348	    /**
349	     * Check whether an email's domain is <em>disposable-adjacent</em>: related to a known disposable
350	     * domain without being exactly on the blocklist. The domain is the text after the last {@code '@'},
351	     * compared case-insensitively. It is disposable-adjacent when its registrable base label (the label
352	     * immediately before the final TLD label, see {@link #registrableBase(String)}) equals that of a
353	     * domain on {@link #DISPOSABLE_EMAIL_DOMAINS} — this catches the same provider under a different TLD
354	     * (e.g. {@code mailinator.net}) and subdomains of a disposable domain (e.g. {@code inbox.tempmail.com})
355	     * — while a domain that is itself exactly on the blocklist is <em>not</em> counted here (it is a hard
356	     * disposable domain, see {@link #isDisposableEmailDomain(String)}, and is rejected outright). A
357	     * {@code null} or empty email, one with no {@code '@'}, or a bare domain with no registrable base is
358	     * not disposable-adjacent.
359	     *
360	     * @param email the owner's email, possibly {@code null}
361	     * @return {@code true} if the email's domain is disposable-adjacent, {@code false} otherwise
362	     */
363	    public static boolean isDisposableAdjacentEmailDomain(String email) {
364	        if (email == null) {
365	            return false;
366	        }
367	        int at = email.lastIndexOf('@');
368	        if (at < 0) {
369	            return false;
370	        }
371	        String domain = email.substring(at + 1).toLowerCase();
372	        if (domain.isEmpty() || DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
373	            return false;
374	        }
375	        String base = registrableBase(domain);
376	        if (base == null) {
377	            return false;
378	        }
379	        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
380	            if (base.equals(registrableBase(disposable))) {
381	                return true;
382	            }
383	        }
384	        return false;
385	    }
386	
387	    /**
388	     * Resolve a domain's registrable base label: the dot-separated label immediately before the final
389	     * TLD label (e.g. {@code mailinator.com} and {@code inbox.mailinator.com} both yield
390	     * {@code mailinator}). This is the shared primitive behind the disposable-adjacent comparison in
391	     * {@link #isDisposableAdjacentEmailDomain(String)}, so an exact-TLD match is not required.
392	     *
393	     * @param domain the lower-cased domain, never {@code null}
394	     * @return the registrable base label, or {@code null} when the domain has fewer than two labels
395	     */
396	    private static String registrableBase(String domain) {
397	        int lastDot = domain.lastIndexOf('.');
398	        if (lastDot <= 0) {
399	            return null;
400	        }
401	        int prevDot = domain.lastIndexOf('.', lastDot - 1);
402	        return domain.substring(prevDot + 1, lastDot);
403	    }
404	
405	    /**
406	     * Resolve this owner's {@code riskFlag}: whether the owner warrants a manual risk review. It is
407	     * {@code true} when any of three conditions holds, and {@code false} otherwise:
408	     * <ul>
409	     *   <li>the owner is a possible duplicate ({@link #getPossibleDuplicate()} is {@code true}),</li>
410	     *   <li>the owner's email domain is disposable-adjacent (see
411	     *       {@link #isDisposableAdjacentEmailDomain(String)}), or</li>
412	     *   <li>the owner's city is over its soft capacity — the {@code capacityWarning} band
413	     *       ({@link #getCapacityWarning()} is {@code true}), i.e. the city was at or above the
414	     *       capacity-warning threshold when the owner was created.</li>
415	     * </ul>
416	     * A {@code null} stored {@code possibleDuplicate} or {@code capacityWarning} is read as
417	     * {@code false}.
418	     *
419	     * @return {@code true} if any risk condition holds, {@code false} otherwise
420	     */
421	    public boolean riskFlag() {
422	        return Boolean.TRUE.equals(this.possibleDuplicate)
423	            || isDisposableAdjacentEmailDomain(this.email)
424	            || Boolean.TRUE.equals(this.capacityWarning);
425	    }
426	
427	    /**
428	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
429	     * truth for how a telephone is compared and persisted, so inputs that differ only in
430	     * formatting (spaces, dashes, brackets) are treated as the same number.
431	     *
432	     * <p>The rules are:
433	     * <ul>
434	     *   <li>spaces, dashes and brackets are stripped;</li>
435	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
436	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
437	     *       is dropped from the national digits;</li>
438	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
439	     *   <li>for a recognized country code the national number (the digits after the country
440	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
441	     *       digits and {@code '+1'} requires 10.</li>
442	     * </ul>
443	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
444	     * values are returned unchanged.
445	     *
446	     * @param telephone the raw telephone, possibly {@code null}
447	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
448	     *     valid E.164 number
449	     */
450	    public static String normalizeTelephone(String telephone) {
451	        if (telephone == null) {
452	            return null;
453	        }
454	        String trimmed = telephone.trim();
455	        boolean hasCountryCode = trimmed.startsWith("+");
456	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
457	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
458	        if (hasCountryCode) {
459	            stripped = stripped.substring(1);
460	        }
461	        if (!stripped.matches("\\d+")) {
462	            return null;
463	        }
464	        String digits;
465	        if (hasCountryCode) {
466	            digits = stripped;
467	        } else {
468	            if (stripped.startsWith("0")) {
469	                stripped = stripped.substring(1);
470	            }
471	            digits = "61" + stripped;
472	        }
473	        if (digits.length() < 8 || digits.length() > 15) {
474	            return null;
475	        }
476	        if (!hasValidNationalNumberLength(digits)) {
477	            return null;
478	        }
479	        return "+" + digits;
480	    }
481	
482	    /**
483	     * Format a stored E.164 telephone for human display: the country code, a space, then the
484	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
485	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
486	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
487	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
488	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
489	     * kept unchanged elsewhere.
490	     *
491	     * @param telephone the stored E.164 telephone, possibly {@code null}
492	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
493	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
494	     *     unchanged
495	     */
496	    public static String telephoneDisplay(String telephone) {
497	        if (telephone == null) {
498	            return null;
499	        }
500	        if (!telephone.matches("\\+\\d+")) {
501	            return telephone;
502	        }
503	        String digits = telephone.substring(1);
504	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
505	            if (digits.startsWith(countryCode)) {
506	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
507	            }
508	        }
509	        return "+" + groupDigits(digits);
510	    }
511	
512	    /**
513	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
514	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
515	     * {@code "412345678"} becomes {@code "412 345 678"}).
516	     *
517	     * @param digits the national digits
518	     * @return the space-grouped digits
519	     */
520	    private static String groupDigits(String digits) {
521	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
522	        for (int i = 0; i < digits.length(); i++) {
523	            if (i > 0 && i % 3 == 0) {
524	                grouped.append(' ');
525	            }
526	            grouped.append(digits.charAt(i));
527	        }
528	        return grouped.toString();
529	    }
530	
531	    /**
532	     * Required national-number length (the count of digits after the country code) for each
533	     * recognized country code, longest country code first so the prefix match is unambiguous.
534	     */
535	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
536	    static {
537	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
538	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
539	    }
540	
541	    /**
542	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
543	     * length its country code requires. A country code with no registered length places no
544	     * additional constraint and is accepted.
545	     *
546	     * @param digits the E.164 digits without the leading {@code '+'}
547	     * @return {@code true} if the national-number length is valid for the country code
548	     */
549	    private static boolean hasValidNationalNumberLength(String digits) {
550	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
551	            String countryCode = entry.getKey();
552	            if (digits.startsWith(countryCode)) {
553	                return digits.length() - countryCode.length() == entry.getValue();
554	            }
555	        }
556	        return true;
557	    }
558	
559	    /**
560	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
561	     * upper-cased abbreviation.
562	     */
563	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
564	        "ST", "STREET",
565	        "RD", "ROAD",
566	        "AVE", "AVENUE");
567	
568	    /**
569	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
570	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
571	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
572	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
573	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
574	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
575	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
576	     * value. The transform is idempotent: a normalized address normalizes to itself.
577	     *
578	     * @param address the raw address, possibly {@code null}
579	     * @return the normalized form, or {@code null} if the input was {@code null}
580	     */
581	    public static String normalizeAddress(String address) {
582	        if (address == null) {
583	            return null;
584	        }
585	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
586	        if (collapsed.isEmpty()) {
587	            return collapsed;
588	        }
589	        String[] tokens = collapsed.split(" ");
590	        StringBuilder normalized = new StringBuilder(collapsed.length());
591	        for (int i = 0; i < tokens.length; i++) {
592	            if (i > 0) {
593	                normalized.append(' ');
594	            }
595	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
596	        }
597	        return normalized.toString();
