665	    /**
666	     * The fixed version tag mixed into the version-2 owner identifiers&mdash;the {@link
667	     * #householdId(String, String) householdId}, the {@link #identityKey(String, String, String)
668	     * identityKey} and the {@link #memberId(String, String, String, LocalDate) memberId} (through its
669	     * {@link #identityRegion(String) region code}). Mixing this tag into each derivation makes every
670	     * version-2 identifier differ from the value version 1 would have produced for the same owner. The
671	     * tag appears only inside the identifiers, never in the user-facing {@code locality},
672	     * {@code timezone} or {@code ownerSegment}.
673	     */
674	    private static final String IDENTITY_VERSION = "V2";
675	
676	    /**
677	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
678	     * last name (compared case-insensitively with collapsed whitespace, see
679	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
680	     * those two fields, so two owners who share a last name and postcode are assigned the same id
681	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
682	     * upper-cased hex characters of the SHA-256 digest of
683	     * {@code IDENTITY_VERSION + '|' + normalizedLastName + '|' + postcode}. The fixed
684	     * {@link #IDENTITY_VERSION 'V2'} version tag mixed into the digest makes the version-2 household id
685	     * differ from the version-1 value for the same owner.
686	     *
687	     * @param lastName the owner's last name, possibly {@code null}
688	     * @param postcode the owner's postcode, possibly {@code null}
689	     * @return the household id, or {@code null} if either field is {@code null}
690	     */
691	    public static String householdId(String lastName, String postcode) {
692	        String normalizedLastName = normalizeHousehold(lastName);
693	        if (normalizedLastName == null || postcode == null) {
694	            return null;
695	        }
696	        String key = IDENTITY_VERSION + "|" + normalizedLastName + "|" + postcode;
697	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
698	    }
699	
700	    /**
701	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
702	     * shared primitive behind every hash-derived owner value (the household id and the member id's
703	     * HASH8 segment), so they all agree on algorithm and encoding.
704	     *
705	     * @param value the string to digest, never {@code null}
706	     * @return the 64-character lower-case hex digest
707	     */
708	    private static String sha256Hex(String value) {
709	        try {
710	            byte[] digest = MessageDigest.getInstance("SHA-256")
711	                .digest(value.getBytes(StandardCharsets.UTF_8));
712	            StringBuilder hex = new StringBuilder(digest.length * 2);
713	            for (byte b : digest) {
714	                hex.append(String.format("%02x", b));
715	            }
716	            return hex.toString();
717	        } catch (NoSuchAlgorithmException e) {
718	            // SHA-256 is a standard algorithm required to be present on every JVM.
719	            throw new IllegalStateException("SHA-256 not available", e);
720	        }
721	    }
