766	    /**
767	     * Resolve the version-2 region code mixed into the owner identifiers: the owner's plain region
768	     * code (see {@link #regionForPostcode(String)}, or {@code 'UNKNOWN'} when no region can be derived)
769	     * with the fixed {@link #IDENTITY_VERSION 'V2'} tag appended (e.g. {@code 'NSWV2'},
770	     * {@code 'UNKNOWNV2'}). This is the region code carried <em>inside</em> the {@code memberId}; the
771	     * user-facing {@code locality} keeps the plain region code (see {@link #locality(String)}), so the
772	     * {@code 'V2'} tag never leaks into the locality, timezone or owner segment.
773	     *
774	     * @param postcode the owner's postcode, possibly {@code null}
775	     * @return the version-2 region code, never {@code null}
776	     */
777	    private static String identityRegion(String postcode) {
778	        String region = regionForPostcode(postcode);
779	        if (region == null) {
780	            region = "UNKNOWN";
781	        }
782	        return region + IDENTITY_VERSION;
783	    }
