820	    /** Soundex digit for each consonant; vowels, {@code H}, {@code W} and {@code Y} map to '0'. */
821	    private static final Map<Character, Character> SOUNDEX_CODES = new HashMap<>();
822	    static {
823	        for (char c : "BFPV".toCharArray()) {
824	            SOUNDEX_CODES.put(c, '1');
825	        }
826	        for (char c : "CGJKQSXZ".toCharArray()) {
827	            SOUNDEX_CODES.put(c, '2');
828	        }
829	        for (char c : "DT".toCharArray()) {
830	            SOUNDEX_CODES.put(c, '3');
831	        }
832	        SOUNDEX_CODES.put('L', '4');
833	        for (char c : "MN".toCharArray()) {
834	            SOUNDEX_CODES.put(c, '5');
835	        }
836	        SOUNDEX_CODES.put('R', '6');
837	    }
838	
839	    /**
840	     * Compute the American Soundex code of a name: the upper-cased first letter followed by three
841	     * digits encoding the following consonants ({@code B,F,P,V}->1; {@code C,G,J,K,Q,S,X,Z}->2;
842	     * {@code D,T}->3; {@code L}->4; {@code M,N}->5; {@code R}->6), padded with zeros to length four.
843	     * Vowels ({@code A,E,I,O,U,Y}) separate codes; {@code H} and {@code W} are ignored so two
844	     * like-coded consonants on either side of them collapse to a single digit; adjacent letters with
845	     * the same code also collapse to one. Non-letters are stripped before coding. This is the single
846	     * source of truth for the surname component of the {@code identityKey} and the soft-match rule.
847	     *
848	     * @param name the raw name, possibly {@code null}
849	     * @return the four-character Soundex code, {@code null} if the input is {@code null}, or the empty
850	     *     string if the input contains no letters
851	     */
852	    public static String soundex(String name) {
853	        if (name == null) {
854	            return null;
855	        }
856	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
857	        if (letters.isEmpty()) {
858	            return "";
859	        }
860	        StringBuilder code = new StringBuilder();
861	        code.append(letters.charAt(0));
862	        char previous = SOUNDEX_CODES.getOrDefault(letters.charAt(0), '0');
863	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
864	            char c = letters.charAt(i);
865	            if (c == 'H' || c == 'W') {
866	                continue;
867	            }
868	            char digit = SOUNDEX_CODES.getOrDefault(c, '0');
869	            if (digit != '0' && digit != previous) {
870	                code.append(digit);
871	            }
872	            previous = digit;
873	        }
874	        while (code.length() < 4) {
875	            code.append('0');
876	        }
877	        return code.toString();
878	    }
