1059	     * @return the owner's {@code '<TIER>_<AREA>'} segment
1060	     */
1061	    public String ownerSegment() {
1062	        String tier = effectiveMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
1063	        String area = KNOWN_REGIONS.contains(locality(this.postcode)) ? "METRO" : "REGIONAL";
1064	        return tier + "_" + area;
1065	    }
1066	
1067	    /**
1068	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
1069	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
1070	     *
1071	     * @param city the owner's city, possibly {@code null}
1072	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
1073	     */
1074	    private static String regionForCity(String city) {
1075	        if (city == null) {
1076	            return "UNKNOWN";
1077	        }
1078	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
1079	    }
1080	
1081	    /**
1082	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
1083	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
1084	     * inclusive low and high bound of the region's valid 4-digit postcodes
1085	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
1086	     * table (including {@code 'UNKNOWN'}) places no range constraint.
1087	     */
1088	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
1089	        "NSW", new int[] {2000, 2099},
1090	        "VIC", new int[] {3000, 3099},
1091	        "QLD", new int[] {4000, 4099});
1092	
1093	    /**
1094	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
1095	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
1096	     * digits, or one that falls in no known range resolves to {@code null}.
1097	     *
1098	     * @param postcode the owner's postcode, possibly {@code null}
1099	     * @return the matching region, or {@code null} when no range contains the postcode
1100	     */
1101	    private static String regionForPostcode(String postcode) {
1102	        if (postcode == null || !postcode.matches("\\d{4}")) {
1103	            return null;
1104	        }
1105	        int value = Integer.parseInt(postcode);
1106	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
1107	            int[] range = entry.getValue();
1108	            if (value >= range[0] && value <= range[1]) {
1109	                return entry.getKey();
1110	            }
1111	        }
1112	        return null;
1113	    }
1114	
1115	    /**
1116	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
1117	     * {@code null} or empty postcode is always valid. When present it must be exactly four
1118	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
1119	     * range the value must fall within that inclusive range. A city with no known region accepts
1120	     * any four-digit postcode. This is the single source of
1121	     * truth for postcode validity, shared by the DTO validation and any persistence path.
1122	     *
1123	     * @param postcode the owner's postcode, possibly {@code null}
1124	     * @param city the owner's city, possibly {@code null}
1125	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
1126	     */
1127	    public static boolean isPostcodeValidForCity(String postcode, String city) {
1128	        if (postcode == null || postcode.isEmpty()) {
1129	            return true;
1130	        }
1131	        if (!postcode.matches("\\d{4}")) {
1132	            return false;
1133	        }
1134	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
1135	        if (range == null) {
1136	            return true;
1137	        }
1138	        int value = Integer.parseInt(postcode);
1139	        return value >= range[0] && value <= range[1];
1140	    }
1141	
1142	    /**
1143	     * Compute a single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
1144	     * characters are ignored. This is the standard Luhn check digit: each digit is weighted
1145	     * right-to-left, every second digit (starting with the rightmost) is doubled with digit sums above
1146	     * nine reduced by nine, and the check digit is the amount that brings the weighted sum up to the
1147	     * next multiple of ten. It is the shared primitive behind the {@code CHK} segment of the
1148	     * {@code memberId} (see {@link #memberId(String, String, String, LocalDate)}).
1149	     *
1150	     * @param value the string whose digits are summed, never {@code null}
1151	     * @return the Luhn check digit from 0 to 9
1152	     */
1153	    private static int luhn(String value) {
1154	        int sum = 0;
1155	        boolean dbl = true;
1156	        for (int i = value.length() - 1; i >= 0; i--) {
1157	            char c = value.charAt(i);
1158	            if (c < '0' || c > '9') {
1159	                continue;
1160	            }
1161	            int d = c - '0';
1162	            if (dbl) {
1163	                d *= 2;
1164	                if (d > 9) {
1165	                    d -= 9;
1166	                }
1167	            }
1168	            sum += d;
1169	            dbl = !dbl;
1170	        }
1171	        return (10 - (sum % 10)) % 10;
1172	    }
1173	
1174	    /**
1175	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
1176	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
1177	     * is deterministic in the email.
1178	     *
1179	     * @param email the owner's email, possibly {@code null}
1180	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
1181	     */
1182	    public static String contactPreference(String email) {
1183	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
1184	    }
1185	
1186	    /**
1187	     * Compose an owner's {@code salutation} from the optional honorific title and the last name.
1188	     * When a title is present the result is the title and the last name separated by a single space
1189	     * (e.g. {@code 'DR Franklin'}); when no title is given the result is just the last name. The
1190	     * value is deterministic in those two fields.
1191	     *
1192	     * @param title the owner's honorific title, possibly {@code null} or blank
1193	     * @param lastName the owner's last name, possibly {@code null}
1194	     * @return the composed salutation
1195	     */
1196	    public static String salutation(String title, String lastName) {
1197	        if (title == null || title.isBlank()) {
1198	            return lastName;
1199	        }
1200	        return title + " " + lastName;
1201	    }
1202	
1203	    /**
1204	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
1205	     * date. The age in whole years is the number of completed years between {@code birthDate} and
1206	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
1207	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
1208	     * two fields and is only defined when both are present.
1209	     *
1210	     * @param birthDate the owner's date of birth, possibly {@code null}
1211	     * @param registrationDate the owner's registration date, possibly {@code null}
1212	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
1213	     *     is {@code null}
1214	     */
1215	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
1216	        if (birthDate == null || registrationDate == null) {
1217	            return null;
1218	        }
1219	        int age = Period.between(birthDate, registrationDate).getYears();
1220	        if (age < 18) {
1221	            return "MINOR";
1222	        }
1223	        if (age < 65) {
1224	            return "ADULT";
1225	        }
1226	        return "SENIOR";
1227	    }
1228	
1229	    protected Set<Pet> getPetsInternal() {
1230	        if (this.pets == null) {
1231	            this.pets = new HashSet<>();
1232	        }
1233	        return this.pets;
1234	    }
1235	
1236	    protected void setPetsInternal(Set<Pet> pets) {
1237	        this.pets = pets;
1238	    }
1239	
1240	    public List<Pet> getPets() {
1241	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
1242	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
1243	        return Collections.unmodifiableList(sortedPets);
1244	    }
1245	
1246	    public void setPets(List<Pet> pets) {
1247	        this.pets = new HashSet<>(pets);
1248	    }
1249	
1250	    public void addPet(Pet pet) {
1251	        getPetsInternal().add(pet);
1252	        pet.setOwner(this);
1253	    }
1254	
1255	    /**
1256	     * Return the Pet with the given name, or null if none found for this Owner.
1257	     *
1258	     * @param name to test
1259	     * @return true if pet name is already in use
1260	     */
1261	    public Pet getPet(String name) {
1262	        return getPet(name, false);
1263	    }
1264	
1265	    /**
1266	     * Return the Pet with the given name, or null if none found for this Owner.
1267	     *
1268	     * @param name to test
1269	     * @return true if pet name is already in use
1270	     */
1271	    public Pet getPet(String name, boolean ignoreNew) {
1272	        name = name.toLowerCase();
1273	        for (Pet pet : getPetsInternal()) {
1274	            if (!ignoreNew || !pet.isNew()) {
1275	                String compName = pet.getName();
1276	                compName = compName.toLowerCase();
1277	                if (compName.equals(name)) {
1278	                    return pet;
1279	                }
1280	            }
1281	        }
1282	        return null;
1283	    }
1284	
1285	    public Pet getPet(Integer petId) {
1286	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
1287	    }
1288	
1289	    @Override
1290	    public String toString() {
1291	        return new ToStringCreator(this)
1292	
1293	            .append("id", this.getId())
1294	            .append("new", this.isNew())
1295	            .append("lastName", this.getLastName())
1296	            .append("firstName", this.getFirstName())
1297	            .append("address", this.address)
1298	            .append("city", this.city)
1299	            .append("telephone", this.telephone)
1300	            .toString();
1301	    }
1302	}
